std::random_device rd;
std::mt19937 gen(rd());
const double kB = 1.0; // Boltzmann constant in reduced units

// Sample velocities from Maxwell‑Boltzmann distribution
for (size_t i = 0; i < velocities.size(); ++i) {
    double sigma = std::sqrt(kB * temperature / masses[i]);
    std::normal_distribution<double> dist(0.0, sigma);
    velocities[i] = vec3(dist(gen), dist(gen), dist(gen));
}

// Compute total momentum and total mass
vec3 momentumSum(0.0, 0.0, 0.0);
double totalMass = 0.0;
for (size_t i = 0; i < velocities.size(); ++i) {
    momentumSum += velocities[i] * masses[i];
    totalMass += masses[i];
}

// Remove center‑of‑mass motion
if (totalMass > 0.0) {
    vec3 comVelocity = momentumSum / totalMass;
    for (size_t i = 0; i < velocities.size(); ++i) {
        velocities[i] -= comVelocity;
    }
}

